import sys


def main():
    data = sys.stdin.read().split()
    n, m, k = int(data[0]), int(data[1]), int(data[2])
    grid = data[3:3 + n]
    inf = float('inf')
    dist = {}
    for r in range(n):
        for c in range(m):
            for b in range(k + 1):
                dist[(r, c, b)] = inf
    dist[(0, 0, 0)] = 0
    changed = True
    while changed:
        changed = False
        for (r, c, b), d in list(dist.items()):
            if d == inf:
                continue
            for nr, nc in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):
                if nr < 0 or nr >= n or nc < 0 or nc >= m:
                    continue
                nb = b + 1 if grid[nr][nc] == '1' else b
                if nb > k:
                    continue
                if d + 1 < dist[(nr, nc, nb)]:
                    dist[(nr, nc, nb)] = d + 1
                    changed = True
    best = min(dist[(n - 1, m - 1, b)] for b in range(k + 1))
    print(-1 if best == inf else best)


main()
